    """pipe user input that wasnt caught by intents to the game
    do any intent matching or normalization here
    don't forget to self.speak the game output too!

    The active layer is resolved from the current session, so concurrent
    sessions in different stages route to the right branch.
    """
    self.log.debug("Skill intents wont trigger, handle game action in converse")

    # resolve which layer THIS session is in (per-session gating)
    from ovos_bus_client.session import SessionManager
    sess = SessionManager.get(message) if message else None

    def active(layer):
        return self.intent_layers.is_active(layer, sess)

    # take corrective action when no intent matched
    if active("guard") or active("guard2"):
        self.speak_dialog("guard_dead")
